mapper.select:
SELECT l.id AS id, l.product_id AS productId, p.store_name AS productName, p.image AS productImage, l.attr_value_id AS attrValueId, IFNULL(v.suk, '') AS skuName, l.type AS type, l.quantity AS quantity, l.before_stock AS beforeStock, l.after_stock AS afterStock, l.relation_id AS relationId, l.relation_type AS relationType, l.operator_name AS operatorName, l.remark AS remark, l.create_time AS createTime FROM eb_stock_log l LEFT JOIN eb_store_product p ON p.id = l.product_id LEFT JOIN eb_store_product_attr_value v ON v.id = l.attr_value_id WHERE 1 = 1
AND l.product_id = #{productId}
AND l.type = #{type}
ORDER BY l.id DESC

SELECT type, SUM(CASE WHEN quantity > 0 THEN quantity ELSE 0 END) AS inQuantity, SUM(CASE WHEN quantity < 0 THEN -quantity ELSE 0 END) AS outQuantity, SUM(quantity) AS netQuantity FROM eb_stock_log WHERE 1 = 1
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY type ORDER BY type ASC
